import{_ as e,o as i,c as s,ai as t}from"./chunks/framework.CaiDwmc7.js";const c=JSON.parse('{"title":"Panduan Devilbox","description":"","frontmatter":{},"headers":[],"relativePath":"devilbox-guide.md","filePath":"devilbox-guide.md"}'),n={name:"devilbox-guide.md"};function l(d,a,r,h,o,p){return i(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="panduan-devilbox" tabindex="-1">Panduan Devilbox <a class="header-anchor" href="#panduan-devilbox" aria-label="Permalink to “Panduan Devilbox”">​</a></h1><p>Devilbox adalah lingkungan pengembangan lokal (local development environment) berbasis Docker yang sangat fleksibel dan mudah disesuaikan. Devilbox mendukung stack LAMP (Linux, Apache/Nginx, MySQL/MariaDB, PHP) serta stack MEAN, Node, Python, dan Go.</p><h2 id="persiapan-awal" tabindex="-1">Persiapan Awal <a class="header-anchor" href="#persiapan-awal" aria-label="Permalink to “Persiapan Awal”">​</a></h2><ol><li><p><strong>Clone Repositori Devilbox</strong></p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/cytopia/devilbox</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> devilbox</span></span></code></pre></div></li><li><p><strong>Konfigurasi Environment</strong> Salin file contoh konfigurasi:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> env-example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><p>Buka file <code>.env</code> dan sesuaikan versi software yang dibutuhkan (misal: <code>PHP_SERVER</code>, <code>HTTPD_SERVER</code>, <code>MYSQL_SERVER</code>).</p></li></ol><h2 id="daftar-layanan-utama" tabindex="-1">Daftar Layanan Utama <a class="header-anchor" href="#daftar-layanan-utama" aria-label="Permalink to “Daftar Layanan Utama”">​</a></h2><p>Daftar layanan asli yang dapat dijalankan di dalam Devilbox antara lain:</p><ul><li><code>httpd</code>: Web Server (Apache atau Nginx).</li><li><code>php</code>: PHP-FPM.</li><li><code>mysql</code>: Database MySQL atau MariaDB.</li><li><code>pgsql</code>: Database PostgreSQL.</li><li><code>redis</code>: Redis server.</li><li><code>memcd</code>: Memcached server.</li><li><code>mongo</code>: MongoDB server.</li></ul><h2 id="konfigurasi-web-server" tabindex="-1">Konfigurasi Web Server <a class="header-anchor" href="#konfigurasi-web-server" aria-label="Permalink to “Konfigurasi Web Server”">​</a></h2><p>Anda dapat memilih antara Apache atau Nginx melalui variabel <code>HTTPD_SERVER</code> di file <code>.env</code>:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Untuk Apache 2.4</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HTTPD_SERVER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">apache-2.4</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Untuk Nginx Stable</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HTTPD_SERVER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nginx-stable</span></span></code></pre></div><p>Setelah mengubah <code>.env</code>, jalankan kembali container:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker-compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> httpd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> php</span></span></code></pre></div><h2 id="konfigurasi-database" tabindex="-1">Konfigurasi Database <a class="header-anchor" href="#konfigurasi-database" aria-label="Permalink to “Konfigurasi Database”">​</a></h2><p>Devilbox mendukung berbagai jenis database secara bersamaan.</p><h3 id="_1-mysql-mariadb" tabindex="-1">1. MySQL / MariaDB <a class="header-anchor" href="#_1-mysql-mariadb" aria-label="Permalink to “1. MySQL / MariaDB”">​</a></h3><p>Pilih versi melalui <code>MYSQL_SERVER</code> (misal: <code>mysql-8.0</code> atau <code>mariadb-10.6</code>).</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker-compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql</span></span></code></pre></div><h3 id="_2-postgresql" tabindex="-1">2. PostgreSQL <a class="header-anchor" href="#_2-postgresql" aria-label="Permalink to “2. PostgreSQL”">​</a></h3><p>Pastikan layanan <code>pgsql</code> diaktifkan di perintah start:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker-compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pgsql</span></span></code></pre></div><h2 id="perintah-dasar-layanan" tabindex="-1">Perintah Dasar Layanan <a class="header-anchor" href="#perintah-dasar-layanan" aria-label="Permalink to “Perintah Dasar Layanan”">​</a></h2><p>Semua perintah dijalankan di dalam direktori <code>devilbox/</code>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Aksi</th><th style="text-align:left;">Perintah</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Menjalankan Stack Standar</strong></td><td style="text-align:left;"><code>docker-compose up -d httpd php mysql</code></td></tr><tr><td style="text-align:left;"><strong>Menjalankan Stack Postgres</strong></td><td style="text-align:left;"><code>docker-compose up -d httpd php pgsql</code></td></tr><tr><td style="text-align:left;"><strong>Menghentikan Layanan</strong></td><td style="text-align:left;"><code>docker-compose stop</code></td></tr><tr><td style="text-align:left;"><strong>Melihat Status</strong></td><td style="text-align:left;"><code>docker-compose ps</code></td></tr><tr><td style="text-align:left;"><strong>Masuk ke Shell PHP</strong></td><td style="text-align:left;"><code>./shell.sh</code></td></tr><tr><td style="text-align:left;"><strong>Menghapus Container</strong></td><td style="text-align:left;"><code>docker-compose rm -f</code></td></tr></tbody></table><h2 id="konfigurasi-proyek" tabindex="-1">Konfigurasi Proyek <a class="header-anchor" href="#konfigurasi-proyek" aria-label="Permalink to “Konfigurasi Proyek”">​</a></h2><ol><li>Letakkan folder proyek Anda di dalam direktori <code>data/www/</code>.</li><li>Struktur folder harus mengikuti: <code>data/www/&lt;nama_proyek&gt;/htdocs</code>.</li><li>Akses proyek melalui browser: <code>http://&lt;nama_proyek&gt;.loc</code>.</li></ol><p><em>Catatan: Anda mungkin perlu menambahkan <code>&lt;nama_proyek&gt;.loc</code> ke file <code>/etc/hosts</code> Anda.</em></p><h2 id="intranet-dashboard" tabindex="-1">Intranet Dashboard <a class="header-anchor" href="#intranet-dashboard" aria-label="Permalink to “Intranet Dashboard”">​</a></h2><p>Setelah Devilbox berjalan, silakan akses <code>http://localhost</code> untuk membuka dashboard intranet. Di sana Anda dapat melihat status layanan, database, dan daftar virtual host yang tersedia.</p>`,28)])])}const g=e(n,[["render",l]]);export{c as __pageData,g as default};
